contract InvMutTest {
    C c;
    address distributor;

    constructor(C _c) {
        c = _c;
        // record the distributor configured in the deployed contract
        distributor = c.rewardDistributor();
    }

    // single public property test entry
    // We take a reward token address and an amount. The distributor (msg.sender for the notify) must be the configured distributor.
    // Because the checker will call run(...) once and this contract is the deployer of c, msg.sender for c calls will be this contract.
    function run(address rewardToken, uint256 amount) public payable {
        require(distributor == address(this), "test requires this contract to be distributor");
        // Precondition: reward token must have been added by owner previously (rewardData.lastUpdateTime != 0)
        // We check rewardPeriodFinish to infer existence: addReward sets lastUpdateTime and periodFinish to block.timestamp
        uint40 beforeFinish = c.rewardPeriodFinish(rewardToken);
        // If the token is unknown the contract would revert in notifyRewardAmount; we only proceed when it's known.
        require(beforeFinish != 0, "unknown reward token");
        // amount must be > 0 per notifyRewardAmount
        require(amount > 0, "No reward");

        // Read rewardPerToken and rewardPeriodFinish before the call to observe changes
        uint256 beforeRPT = c.rewardPerToken(rewardToken);

        bool reverted;
        // call notifyRewardAmount; per contract it requires msg.sender == rewardDistributor (we ensured that)
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint40 afterFinish = c.rewardPeriodFinish(rewardToken);
        uint256 afterRPT = c.rewardPerToken(rewardToken);

        // General rule: when preconditions hold (known token, distributor == this, amount>0), notifyRewardAmount must NOT revert
        // and it must update periodFinish to be strictly in the future (greater or equal to block.timestamp) and rewardPerToken should be >= before value.
        assert(!reverted && uint256(afterFinish) >= block.timestamp && afterRPT >= beforeRPT);
    }

    receive() external payable {}
}

