contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: distributor must be the caller when notifyRewardAmount is invoked by this test
    // We model calls by having this contract act as the distributor; caller of run supplies
    // _rewardToken that must have been previously added by owner. Since the checker deploys a fresh C
    // and this contract deployed it, deployer is the test contract and thus owner. So we can call addReward.

    function run(address _rewardToken, uint256 _amount) public payable {
        require(_rewardToken != address(0), true);
        // As the deployer of C (per harness) this contract is owner; add the reward token to make it known.
        c.addReward(_rewardToken);

        // set rewardDistributor to this contract so notifyRewardAmount call will be allowed
        c.setRewardDistributor(address(this));

        // approve the contract to pull rewards: the test cannot mint ERC20, but notifyRewardAmount will try
        // to transferFrom(msg.sender, address(this), _amount). To avoid revert from SafeERC20.safeTransferFrom,
        // choose to pass in _amount == 0 triggers require(_amount > 0) in notifyRewardAmount, so must be >0 and transfer will be attempted.
        // We cannot guarantee an ERC20 transfer will succeed for arbitrary token; instead we will short-circuit by
        // observing the notifyRewardAmount call's revert behavior and assert the general invariant relating to allowed/disallowed caller.

        // Try calling notifyRewardAmount and capture whether it reverts.
        bool reverted;
        try c.notifyRewardAmount(_rewardToken, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read public observable: rewardPeriodFinish and rewardTokens length and entries
        uint40 finish = c.rewardPeriodFinish(_rewardToken);

        // Check if token is in rewardTokens (scan list)
        bool inList = false;
        for (uint256 i = 0; i < c.rewardTokens().length; i++) {
            if (c.rewardTokens(i) == _rewardToken) {
                inList = true;
                break;
            }
        }

        // General rule asserted:
        // If notifyRewardAmount succeeded (did not revert) then the token must be known (inList==true)
        // and its periodFinish must be at least the current block timestamp (i.e., not in the past).
        // If it reverted, we make no claim besides that either the call reverted or the postconditions hold.
        assert(reverted || (inList && finish >= uint40(block.timestamp)));
    }

    // Allow receiving ETH if needed by ERC20 wrappers (unlikely here)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We act as deployer/owner of C (per harness) so we can add reward tokens and set distributor.
    // Params: _rewardToken may be any address, _amount any uint256. The function is non-payable.
    function run(address _rewardToken, uint256 _amount) public payable {
        // no precondition on parameters
        // make sure the reward token is known by adding it (this contract is owner)
        // addReward will revert if token already exists; guard by trying and catching
        bool addedKnown = false;
        {
            bool addReverted;
            try c.addReward(_rewardToken) {
                addReverted = false;
                addedKnown = true;
            } catch {
                addReverted = true;
            }
            // ignore addReverted; if already exists it's fine
        }

        // set this contract as distributor so notifyRewardAmount can be called from here
        c.setRewardDistributor(address(this));

        // Try calling notifyRewardAmount and capture whether it reverts.
        bool reverted;
        try c.notifyRewardAmount(_rewardToken, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable state: rewardPeriodFinish for the token
        uint40 finish = c.rewardPeriodFinish(_rewardToken);

        // Check if token is in rewardTokens by scanning public array. Use its length via a loop until failure.
        bool inList = false;
        // We cannot read the dynamic length directly except by calling rewardTokens(i) until it reverts.
        // But rewardTokens is public, so there is also an auto-generated getter that has a separate length function: rewardTokens(uint256) exists but no length getter; however rewardTokens is public array so a getter rewardTokens(uint256) exists and rewardTokens() length doesn't exist. To get length we attempt increasing indices until a call reverts; but view calls that revert will revert here, so instead we read balances indirectly by trying a reasonable bound. Use a for up to 10 entries to avoid unbounded loops in verifier.
        for (uint256 i = 0; i < 10; i++) {
            // try to read entry i
            bool ok;
            address tok;
            try c.rewardTokens(i) returns (address t) {
                ok = true;
                tok = t;
            } catch {
                ok = false;
                tok = address(0);
            }
            if (!ok) break;
            if (tok == _rewardToken) {
                inList = true;
                break;
            }
        }

        // Assert the general rule: if notifyRewardAmount succeeded then the token must be in the list
        // and its periodFinish must be at least current block.timestamp.
        assert(reverted || (inList && finish >= uint40(block.timestamp)));
    }

    receive() external payable {}
}

