        } catch {
            notifyReverted = true;
        }

        // Read observable state: rewardPeriodFinish
        uint40 finish = c.rewardPeriodFinish(_rewardToken);

        // Check membership in rewardTokens by probing up to 20 entries (safe finite bound)
        bool inList = false;
        for (uint256 i = 0; i < 20; i++) {
            bool ok;
