contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters: distributor address, reward token, amount
    function run(address distributor, address rewardToken, uint256 amount) public payable {
        require(amount > 0, "amount>0");
        // initial setup: deployer (this contract) must be owner of c already per harness; set reward distributor and add reward token
        // setRewardDistributor is onlyOwner, and the test contract is the deployer of c per harness note, so calling is allowed
        c.setRewardDistributor(distributor);

        // owner must add reward token before distributor can notify; addReward is onlyOwner
        c.addReward(rewardToken);

        // simulate distributor approving and sending tokens: we cannot mint tokens, but we can only observe effects when notifyRewardAmount is called by distributor.
        // We will call notifyRewardAmount as the distributor via low-level call from this contract by using Address.functionCall? Not allowed. Instead, we make the call directly by impersonating distributor isn't possible.
        // But the contract requires msg.sender == rewardDistributor in notifyRewardAmount; to exercise that, we call setRewardDistributor to this contract and then call notifyRewardAmount.
        c.setRewardDistributor(address(this));

        // For the observable rule we will call notifyRewardAmount and then check two things:
        // 1) address(c).balance is unchanged by token notify (since tokens are ERC20), so we will observe token balance via IERC20(rewardToken).balanceOf(address(c)).
        // However we cannot call external token contract methods unless through c's public view — but IERC20 is external; we may call IERC20(rewardToken).balanceOf(address(c)). That's allowed (observing external contract).
        // To ensure IERC20 transferFrom inside notifyRewardAmount succeeds, the distributor (this) must have approved the token to c; but we cannot mint tokens. To avoid reliance on token transfer semantics, we instead assert properties that do not require token transfer to succeed: the function will revert if transferFrom fails. So we capture revert behavior.

        // Read pre-values
        uint40 beforePeriodFinish = c.rewardPeriodFinish(rewardToken);

        // Attempt notifyRewardAmount and capture revert
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-values
        uint40 afterPeriodFinish = c.rewardPeriodFinish(rewardToken);

        // General rule: If notifyRewardAmount did not revert then
        //   - the caller must have been rewardDistributor (we set it to this), and
        //   - afterPeriodFinish is >= block.timestamp (periodFinish set to now + DURATION) and different from before (unless already far in future),
        //   - else if it reverted then periodFinish must be unchanged.
        // We express a conservative invariant: If call succeeded then afterPeriodFinish >= beforePeriodFinish && afterPeriodFinish >= uint40(block.timestamp);
        // If call reverted then afterPeriodFinish == beforePeriodFinish.

        assert((!reverted && afterPeriodFinish >= beforePeriodFinish && afterPeriodFinish >= uint40(block.timestamp)) || (reverted && afterPeriodFinish == beforePeriodFinish));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function:
    // - rewardToken must be previously added by owner; amount > 0 to exercise happy path
    function run(address rewardToken, uint256 amount) public payable {
        require(amount > 0, "amount>0");

        // Ensure this contract is the reward distributor so notifyRewardAmount can be called from here.
        // setRewardDistributor is onlyOwner and the harness deployer (this contract) is the owner of c per specification.
        c.setRewardDistributor(address(this));

        // Add the reward token as owner so notifyRewardAmount recognizes it.
        // addReward requires the token not already present.
        // If addReward reverts (token already added), the try/catch below will handle notify's behavior accordingly.
        bool added = true;
        try c.addReward(rewardToken) {
            added = true;
        } catch {
            added = false;
        }

        // Read periodFinish before attempting notify
        uint40 before = c.rewardPeriodFinish(rewardToken);

        // Attempt notifyRewardAmount and capture whether it reverts
        bool reverted;
        try c.notifyRewardAmount(rewardToken, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read periodFinish after attempt
        uint40 after = c.rewardPeriodFinish(rewardToken);

        // General rule:
        // If notifyRewardAmount reverted then periodFinish must be unchanged.
        // If it succeeded then periodFinish must be >= before and >= block.timestamp (i.e., not reduced).
        // Expressed as a single assert over observable values.
        assert((reverted && after == before) || (!reverted && after >= before && after >= uint40(block.timestamp)));
    }

    receive() external payable {}
}

