contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call addReward (onlyOwner) so InvMutTest must be owner — constructor deployed c so this contract is owner.
    // Then we call notifyRewardAmount as the rewardDistributor. To do that we must set rewardDistributor to this contract or to another address.
    // OnlyOwner functions: addReward and setMigrator etc. The contract owner is this contract. We'll set rewardDistributor to this contract, call addReward, then call notifyRewardAmount and check periodFinish >= block.timestamp.

    function run(address rewardToken, uint256 amount) public payable {
        require(rewardToken != address(0), true);
        // set this contract as reward distributor
        c.setRewardDistributor(address(this));
        // add the reward token
