        // instead only observe behavior of withdraw when caller has sufficient balance by first simulating a stake
        // via calling migrateStake/migrateWithdraw paths which internally call _applyStake. The contract exposes setMigrator and migrateStake/migrateWithdraw guarded by onlyMigrator.

        // Set this test contract as migrator so we can credit staker's balance without needing ERC20 transfers.
        // must be done by owner; the deployer of c is the owner and per problem statement the checker deploys c and
        // then calls run() with this contract as msg.sender for calls on c. However onlyOwner requires caller to be owner (which is the deployer of C), not this test contract.
        // We cannot call onlyOwner functions. Alternate approach: use _applyStake indirectly by calling migrateStake which is onlyMigrator; setMigrator is onlyOwner so unavailable.
        // Different approach: rely on stakeFor which requires ERC20 transferFrom - also impossible. Therefore we cannot mutate balances except via migrate* which is gated.
        // But we can at least observe that withdraw reverts when balance < amount and that totalSupply never increases by a withdraw.

        // Read observed values before attempted withdraw
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalance = c.balanceOf(staker);

        // Attempt withdraw from staker by calling withdraw on behalf of staker is not available; withdraw uses msg.sender as staker.
        // So we must call c.withdraw from this contract; that will attempt to withdraw this contract's stake. Use withdrawAmount as parameter.
        // Read this contract's balance in c
        uint256 myBalanceBefore = c.balanceOf(address(this));

        bool reverted;
        // perform withdraw as this contract
        try c.withdraw(withdrawAmount, claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTotal = c.totalSupply();
        uint256 myBalanceAfter = c.balanceOf(address(this));

        // General rule (assert): withdraw never increases totalSupply; if it succeeds then totalSupply decreased by exactly min(withdrawAmount, myBalanceBefore)
        // and this contract's balance decreased by that same amount; if it reverts then myBalanceAfter == myBalanceBefore and totalSupply unchanged.
        // Write this as a single assert expression.

        // Compute expected decrease safely: if withdraw succeeded then effective = (withdrawAmount <= myBalanceBefore) ? withdrawAmount : myBalanceBefore;
        // But if it succeeded while withdrawAmount > myBalanceBefore that would violate contract which should revert. So assert covers both cases.

        assert(
            // totalSupply never increases
            afterTotal <= beforeTotal
            && (
                // if reverted: nothing changed
                (reverted && afterTotal == beforeTotal && myBalanceAfter == myBalanceBefore)
                ||
                // if not reverted: amount withdrawn equals decrease in totalSupply and decrease in this contract's balance, and cannot exceed myBalanceBefore
                (!reverted && myBalanceBefore >= withdrawAmount && beforeTotal - afterTotal == withdrawAmount && myBalanceBefore - myBalanceAfter == withdrawAmount)
            )
        );
