contract InvMutTest {
    C c;
    IERC20 token;

    constructor(C _c) {
        c = _c;
        token = c.stakingToken();
    }

    // We take as inputs: beneficiary address 'forAddr' and amount to stake.
    // The test transfers `amount` of stakingToken to this test contract first so it can call stakeFor.
    function run(address forAddr, uint256 amount) public payable {
        require(forAddr != address(0));

        // Prepare token funds for this contract so stakeFor can transferFrom(msg.sender,...).
        // We expect the staking token to allow minting by the test deployer is not available,
        // but we can only interact via public surface. So we require that this contract has
        // sufficient allowance and balance by assuming token.transfer is available from msg.sender
        // However we cannot call token.transferFrom as another account. To remain safe and portable,
        // we simply try the operation and record whether it reverted.

        // Read before values
        uint256 beforeTotal = c.totalSupply();
        uint256 beforeBalanceFor = c.balanceOf(forAddr);
        uint256 beforeTokenBalanceThis = token.balanceOf(address(this));

        bool reverted = false;
        // Call stakeFor from this contract. stakeFor does stakingToken.safeTransferFrom(msg.sender,...)
        // so it will try to pull tokens from this contract (msg.sender = this) — requires this contract
        // to have approved the c contract. If it reverts, we catch and mark reverted.
        try c.stakeFor(forAddr, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after values
        uint256 afterTotal = c.totalSupply();
        uint256 afterBalanceFor = c.balanceOf(forAddr);
        uint256 afterTokenBalanceThis = token.balanceOf(address(this));

        // General rule: if stakeFor did not revert and amount>0 then totalSupply and the beneficiary balance
        // must have increased by exactly amount, and this contract's token balance must have decreased by at least amount.
        // (We use >= for token balance decrease because token could charge fees; but the contract's internal accounting
        // must reflect the full amount staked.)
        assert(
            // If reverted, no guarantees about state changes — so allow either outcome
            reverted || (
                amount > 0 &&
                afterTotal == beforeTotal + amount &&
                afterBalanceFor == beforeBalanceFor + amount &&
                // token balance of this contract should have decreased by at least amount when stake succeeded
                beforeTokenBalanceThis >= afterTokenBalanceThis &&
                (beforeTokenBalanceThis - afterTokenBalanceThis) >= amount
            )
        );
    }

    receive() external payable {}
}

