        require(staker != address(0));

        // ensure this contract has enough staking tokens to transferFrom when calling stakeFor
        // The test harness must ensure token.balanceOf(address(this)) >= approveAmount off-chain or via pre-funding.
        // Approve the c contract to pull tokens from this test contract
        // Note: token is IERC20 and its functions are external, so call directly
        // If approve fails or stakeFor will revert, we capture that via try/catch

        // read before-values
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(staker);

        // attempt to have this contract transfer tokens from msg.sender (InvMutTest) via stakeFor call
        // First, approve c to take tokens from this contract (the stakingToken.safeTransferFrom in stakeFor uses msg.sender as caller)
        // So we must ensure that stakeFor is called by this contract but transfers from msg.sender — however stakeFor uses msg.sender for transferFrom.
        // To model a realistic call, we call c.stakeFor(staker, stakeAmount) where this contract is msg.sender.
        // Approve c to spend tokens held by this contract
        bool approved;
        try token.approve(address(c), approveAmount) returns (bool ok) {
            approved = ok;
        } catch {
            approved = false;
        }

        bool reverted;
        // perform the state-changing call: stakeFor by this contract
        try c.stakeFor(staker, stakeAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(staker);

        // General property asserted:
        // If the call did NOT revert, then approve must have succeeded (so transferFrom could have been allowed)
        // and both totalSupply and staker balance increased by exactly stakeAmount.
        // If the call reverted, balances must be unchanged.
        assert(
            (!reverted && approved && totalAfter == totalBefore + stakeAmount && balAfter == balBefore + stakeAmount)
            || (reverted && totalAfter == totalBefore && balAfter == balBefore)
        );
    }

    receive() external payable {}
}

