    // param: staker is the address that will be used to stake via stakeFor (we act as msg.sender when calling c)
    // amountToStake: amount to stake initially
    // withdrawAmount: amount to withdraw in the tested call
    // claim: whether to request claim in withdraw
    function run(address staker, uint256 amountToStake, uint256 withdrawAmount, bool claim) public payable {
        require(staker != address(0) && address(this) != address(0));

        // Precondition: ensure this test contract has enough tokens to stake the requested amount
        // The checker deploys c with this contract as deployer; we cannot mint tokens, so if token.transferFrom will fail
        // the stakeFor call will revert. To make the test general we guard by requiring this contract allowance and balance.
        // However, to satisfy the constraint that we only call public methods on c to observe, we may still attempt calls and catch reverts.

        // Read observable before-values
        uint256 totalBefore = c.totalSupply();
        uint256 balThisBefore = token.balanceOf(address(this));
        uint256 balCBefore = token.balanceOf(address(c));

        // Try to stake: we call stakeFor(staker, amountToStake) as msg.sender. This may revert; capture that.
        bool stakeReverted = false;
        try c.stakeFor(staker, amountToStake) {
            stakeReverted = false;
        } catch {
            stakeReverted = true;
        }

        // Observe totals after stake attempt
        uint256 totalAfterStake = c.totalSupply();
        uint256 balCAfterStake = token.balanceOf(address(c));

        // Now attempt withdraw: as the staker must call withdraw, we call c.withdraw(withdrawAmount, claim)
        // Note: in original contract withdraw withdraws for msg.sender. Here msg.sender is this test contract.
        // So only meaningful if this contract has a balance. Capture revert.
        bool withdrawReverted = false;
        try c.withdraw(withdrawAmount, claim) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Observe after withdraw
        uint256 totalAfter = c.totalSupply();
        uint256 balCAfter = token.balanceOf(address(c));
        uint256 balThisAfter = token.balanceOf(address(this));

        // General rule asserted:
        // If withdraw succeeded (did not revert) then totalSupply did not increase (totalAfter <= totalAfterStake)
        // and the contract's token balance decreased by exactly withdrawAmount (unless withdrawAmount was impossible and would have reverted).
        // Also, if withdraw succeeded then this test contract's token balance increased by exactly withdrawAmount.
        // We must express a single assert over observed values.

        assert( (
            // case: withdraw reverted -> nothing required about balances except totalSupply did not increase compared to before
            withdrawReverted && totalAfter <= totalAfterStake
        ) || (
            // case: withdraw succeeded -> totalSupply did not increase and token balances changed by exactly withdrawAmount
            (!withdrawReverted) && totalAfter <= totalAfterStake && balCAfter + withdrawAmount == balCAfterStake && balThisAfter == balThisBefore + withdrawAmount
        ));
    }

    receive() external payable {}
}

