contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(address staker, uint256 amount, bool claim) public payable {
        require(staker != address(0));
        // We must ensure there is some stake to withdraw: try to set up by calling stakeFor from this contract
        // However stakeFor requires transferring stakingToken from msg.sender. As the InvMutTest contract is the msg.sender
        // for those calls, we cannot mint tokens here; so instead we reason about calling withdraw as the staker itself
        // The test will invoke withdraw on c using the account that deployed c (which is this contract).
        // So we simulate by reading pre-state for this contract (as staker = address(this) below) and then performing withdraw
        // Ensure we only call withdraw on behalf of this contract: require staker == address(this)
        require(staker == address(this));

        // Read pre-call observables
        uint256 totalBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(staker);
        uint256 contractEthBefore = address(c).balance;

        // perform the withdraw and capture whether it reverted
        bool reverted;
        try c.withdraw(amount, claim) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read post-call observables
        uint256 totalAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(staker);
        uint256 contractEthAfter = address(c).balance;

        // If the withdraw succeeded, then totalSupply and balanceOf(staker) must have decreased by exactly amount
        // If the withdraw reverted, state should be unchanged (observed values equal)
        assert(
            // successful case
            (!reverted && totalBefore >= amount && balBefore >= amount && totalAfter + amount == totalBefore && balAfter + amount == balBefore)
            // reverted case: no observable change to these public variables
            || (reverted && totalAfter == totalBefore && balAfter == balBefore && contractEthAfter == contractEthBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single entry performing the property check
    // We pick staker == address(this) because only this contract can reliably be msg.sender for setup calls
    function run(address rewardToken) public payable {
        require(rewardToken != address(0));

        address staker = address(this);

        // read prior observable claimable amount and token balance of this contract
        uint256 claimBefore = c.claimableRewards(staker, rewardToken);
        uint256 tokenBalBefore = IERC20(rewardToken).balanceOf(address(this));

        // call getReward (external entry) which uses updateReward modifier and then _getReward
        bool reverted;
        try c.getReward(staker, rewardToken) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 claimAfter = c.claimableRewards(staker, rewardToken);
        uint256 tokenBalAfter = IERC20(rewardToken).balanceOf(address(this));

        // General rule:
        // - If call did not revert and there was a positive claimBefore, then claimAfter == 0 and token balance increased by claimBefore.
        // - If call did not revert and claimBefore == 0, then nothing changed (claim stays zero and token balance unchanged).
        // - If call reverted, the public observables did not increase the token balance (no tokens were received) and claimable may be unchanged.
        assert(
            // successful and had positive claim: balance increased exactly and claim zeroed
            (!reverted && claimBefore > 0 && claimAfter == 0 && tokenBalAfter == tokenBalBefore + claimBefore)
            // successful and nothing to claim: no change
            || (!reverted && claimBefore == 0 && claimAfter == 0 && tokenBalAfter == tokenBalBefore)
            // reverted: contract did not receive tokens for this call (our balance not increased)
            || (reverted && tokenBalAfter == tokenBalBefore)
        );
    }

    receive() external payable {}
}

