        // If call succeeded (not reverted): every reward token's claimable for staker must be zeroed when it was >0 and the token balance of this contract must have increased by at most the sum of those claimables observed before (we only observed one token here so compare that token);
        // If call reverted: this contract's token balance did not increase.
        assert(
            (!reverted && claimBefore > 0 && claimAfter == 0 && tokenBalAfter >= tokenBalBefore && tokenBalAfter - tokenBalBefore == claimBefore)
            || (!reverted && claimBefore == 0 && claimAfter == 0 && tokenBalAfter == tokenBalBefore)
            || (reverted && tokenBalAfter == tokenBalBefore)
        );
    }

