contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single entry performing the property check
    // We use address(this) as staker because this test contract is the caller for setup calls
    function run(address[] memory rewardTokens) public payable {
        // allow empty list, but avoid zero-address tokens in observations
        // no other precondition
        address staker = address(this);

        // read prior observable claimable amounts and token balances for all provided tokens
        uint256 len = rewardTokens.length;
        uint256[] memory claimBefore = new uint256[](len);
        uint256[] memory balBefore = new uint256[](len);
        for (uint256 i = 0; i < len; i++) {
            address t = rewardTokens[i];
            claimBefore[i] = c.claimableRewards(staker, t);
            balBefore[i] = IERC20(t).balanceOf(address(this));
        }

        // perform the state-changing call as a top-level statement and capture whether it reverted
        bool reverted;
        try c.getRewards(staker) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint256[] memory claimAfter = new uint256[](len);
        uint256[] memory balAfter = new uint256[](len);
        for (uint256 i = 0; i < len; i++) {
            address t = rewardTokens[i];
            claimAfter[i] = c.claimableRewards(staker, t);
            balAfter[i] = IERC20(t).balanceOf(address(this));
        }

        // General rule asserted as a single boolean: For every token, if the call succeeded then claimAfter == 0 and balAfter - balBefore == claimBefore;
        // if the call reverted then balAfter == balBefore for that token. Also when succeeded and claimBefore was zero, balances must be equal and claimAfter zero.
        bool ok = true;
        for (uint256 i = 0; i < len; i++) {
            uint256 beforeC = claimBefore[i];
            uint256 afterC = claimAfter[i];
            uint256 beforeB = balBefore[i];
            uint256 afterB = balAfter[i];

            if (!reverted) {
                // call succeeded: claimable must be zero and token balance must increase exactly by prior claimable
                bool balanceIncreasedCorrectly = (afterB >= beforeB) && (afterB - beforeB == beforeC);
                if (!(afterC == 0 && balanceIncreasedCorrectly)) {
                    ok = false;
                    break;
                }
            } else {
                // call reverted: no token balance change
                if (!(afterB == beforeB)) {
                    ok = false;
                    break;
                }
            }
        }

        assert(ok);
    }

    receive() external payable {}
}

